const snapshot = sourceSnapshot(root,inputs,sourceIndex);
const sourceCommit = execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim();
const dirty = Boolean(execFileSync('git',['status','--porcelain','--',...inputs],{cwd:root,encoding:'utf8'}).trim());
const sourceUpdatedAt = execFileSync('git',['log','-1','--format=%cI','--',...inputs],{cwd:root,encoding:'utf8'}).trim();
const meta = {source_updated_at:dirty ? null : sourceUpdatedAt, source_updated_at_status:dirty ? 'Unavailable for modified inputs' : 'Latest committed input change', version:JSON.parse(await read('website/package.json')).version, built_at:new Date().toISOString(), base_commit:sourceCommit, input_snapshot_sha256:snapshot, inputs_differ_from_base:dirty, documents:sources, material_components:'@material/web 2.4.1', source_inputs:inputs};
const label = (en,zh) => `<span class="en">${en}</span><span class="zh" lang="zh-HK">${zh}</span>`;
const ariaLabel = (en,zh) => `aria-label="${esc(`${en} · ${zh}`)}" data-aria-en="${esc(en)}" data-aria-zh="${esc(zh)}"`;
const url = source => bySource.get(source)?.url || `${repository}/blob/main/${source}`;
const logo = `<svg viewBox="0 0 40 44" aria-hidden="true"><path d="M5 12 20 4l15 8-15 8Z" fill="#4052d6"/><path d="m5 21 15 8 15-8v9l-15 8-15-8Z" fill="#8e9bfa"/><path d="m5 12 15 8 15-8v9l-15 8-15-8Z" fill="#6677e8"/></svg>`;
const nav = [ ['Learn by doing',base,'✦','逐步學習'],['Visitor workspace',base+'site/visitor.html','✎','訪客工作區'],['Roadmap',base+'site/roadmap.html','≡','開發路線'],['Reference library',base+'site/library.html','▤','文件參考庫'],['Planning',base+'site/categories/planning.html','◇','規劃'],['Design',base+'site/categories/design.html','▧','設計'],['Wiki',base+'site/categories/wiki.html','◎','Wiki'],['Evidence',base+'site/categories/evidence.html','✓','驗證'],['Downloads & status',base+'site/status.html','↓','下載同狀態'] ];

const provenance = `<div class="provenance"><span class="version-tag">Documentation v${esc(meta.version)}</span><span>Source updated ${meta.source_updated_at ? `<time data-local datetime="${esc(meta.source_updated_at)}">${esc(meta.source_updated_at)}</time>` : 'Unavailable: modified inputs'}</span><span>Built <time data-local datetime="${meta.built_at}">${meta.built_at}</time></span><span>Source ${esc(sourceCommit.slice(0,12))}${dirty ? ' + modified inputs' : ''}</span><span title="SHA-256 of the exact documentation and website input snapshot">Snapshot ${snapshot.slice(0,10)}</span></div>`;
