const pages=['index.html','site/library.html','site/roadmap.html','site/status.html','site/visitor.html',...categories.map(c=>'site/categories/'+c.id+'.html'),...groups.map(g=>'site/roadmap/'+g.id+'.html'),...phases.map(p=>'site/phases/'+p.id.toLowerCase()+'.html'),...documents.map(d=>d.url.slice(base.length))];
